import re, math
from collections import Counter

def tokenize(text):
    return re.findall(r"[a-zA-Z0-9%./-]+", text.lower())

def ngrams(tokens, n):
    return [tuple(tokens[i:i+n]) for i in range(len(tokens)-n+1)]

def rouge_n(ref, hyp, n):
    r = Counter(ngrams(ref, n)); h = Counter(ngrams(hyp, n))
    ov = sum((h & r).values())
    if ov == 0: return (0.0, 0.0, 0.0)
    p = ov / max(1, sum(h.values())); rec = ov / max(1, sum(r.values()))
    f = 2*p*rec/(p+rec)
    return (p, rec, f)

def rouge_l(ref, hyp):
    m = len(ref); n = len(hyp)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            dp[i][j] = dp[i-1][j-1]+1 if ref[i-1]==hyp[j-1] else max(dp[i-1][j], dp[i][j-1])
    lcs = dp[m][n]
    if lcs == 0: return (0.0, 0.0, 0.0)
    p = lcs/n; rec = lcs/m; f = 2*p*rec/(p+rec)
    return (p, rec, f)

def bleu(ref, hyp):
    precs = []
    for n in range(1, 5):
        r = Counter(ngrams(ref, n)); h = Counter(ngrams(hyp, n))
        ov = sum((h & r).values())
        precs.append(ov / max(1, sum(h.values())))
    if any(p == 0 for p in precs) or len(hyp) == 0:
        geo = 0.0
    else:
        geo = math.exp(sum(0.25*math.log(p) for p in precs))
    bp = min(1.0, math.exp(1 - len(ref)/len(hyp))) if len(hyp) > 0 else 0.0
    return bp * geo

article = open("article.txt").read()
ans = {"GPT-4": open("gpt4_answer.txt").read(), "Claude": open("claude_answer.txt").read()}
ref = tokenize(article)

for name in ans:
    hyp = tokenize(ans[name])
    r1 = rouge_n(ref, hyp, 1); r2 = rouge_n(ref, hyp, 2); rl = rouge_l(ref, hyp); b = bleu(ref, hyp)
    print("== " + name + " ==")
    print("words=" + str(len(hyp)))
    print("ROUGE-1 P/R/F: %.3f/%.3f/%.3f" % (r1[0], r1[1], r1[2]))
    print("ROUGE-2 P/R/F: %.3f/%.3f/%.3f" % (r2[0], r2[1], r2[2]))
    print("ROUGE-L P/R/F: %.3f/%.3f/%.3f" % (rl[0], rl[1], rl[2]))
    print("BLEU: %.3f" % b)

facts = ["33.7", "perovskite", "20%", "80%", "inflation reduction act", "floating solar", "offshore", "dogger", "15-megawatt", "260-meter", "50-60", "30-40", "150 gwh", "lfp", "sodium-ion", "iron-air", "3-4", "500 billion", "14 million", "23%", "2050", "grid infrastructure"]
print("== Key-fact coverage (out of " + str(len(facts)) + ") ==")
for name in ans:
    low = ans[name].lower()
    covered = [f for f in facts if f in low]
    print(name + ": " + str(len(covered)) + "/" + str(len(facts)) + " -> " + str(covered))
